// Procesar datos de costos recibidos desde Grasshopper
const data = $input.first().json;

// Configuración
const BUDGET = 280000;
const WARNING_THRESHOLD = 0.90; // 90% del presupuesto

// Calcular métricas
const totalCost = data.total_cost || 0;
const isOverBudget = totalCost > BUDGET;
const isWarning = totalCost > (BUDGET * WARNING_THRESHOLD);
const margin = BUDGET - totalCost;
const marginPercent = (margin / BUDGET * 100).toFixed(1);
const usagePercent = (totalCost / BUDGET * 100).toFixed(1);

// Determinar estado
let status = 'OK';
let statusEmoji = '✅';
if (isOverBudget) {
  status = 'OVER_BUDGET';
  statusEmoji = '🚨';
} else if (isWarning) {
  status = 'WARNING';
  statusEmoji = '⚠️';
}

// Formatear moneda
const formatCurrency = (amount) => {
  return new Intl.NumberFormat('es-MX', {
    style: 'currency',
    currency: 'MXN'
  }).format(amount);
};

// Preparar datos de paneles
const panels = data.panels || {};
const panelSummary = {
  flat: panels.flat?.quantity || 0,
  singleCurve: panels.single_curve?.quantity || 0,
  doubleCurve: panels.double_curve?.quantity || 0,
  total: (panels.flat?.quantity || 0) + 
         (panels.single_curve?.quantity || 0) + 
         (panels.double_curve?.quantity || 0)
};

return [{
  json: {
    // Datos originales
    ...data,

    // Métricas calculadas
    budget: BUDGET,
    totalCost,
    margin,
    marginPercent: parseFloat(marginPercent),
    usagePercent: parseFloat(usagePercent),
    isOverBudget,
    isWarning,
    status,
    statusEmoji,

    // Resumen de paneles
    panelSummary,

    // Formateados para display
    formatted: {
      totalCost: formatCurrency(totalCost),
      budget: formatCurrency(BUDGET),
      margin: formatCurrency(margin),
      timestamp: new Date().toISOString()
    }
  }
}];

